const count = $input.all().length;
console.log('DocIntel Agent — Batch completado: ' + count + ' actas en ' + new Date().toISOString());
return [{ json: { status: 'ok', actas_procesadas: count, timestamp: new Date().toISOString() } }];

// Layer 1: Native PDF text extraction via FastAPI endpoint
// Calls: POST https://docintel-api/ocr/layer1 { file_id, binary_data }
// In production uses pdfplumber — fastest, ~240ms/doc, $0 cost
const fileId = $json.id;
const fileName = $json.name || '';

// Simulate API response for native text extraction
const nativeText = 'ACTA DE ENTREGA ' + fileName + '\nBeneficiario: CAMILA ANDREA VALENCIA OSPINA\nFirma: SI\nHuella: SI';
const charCount = nativeText.length;

return {
  json: {
    ...$json,
    ocr_layer: 1,
    ocr_raw_text: nativeText,
    char_count: charCount,
    layer1_sufficient: charCount > 150,
    layer1_confidence: charCount > 150 ? 0.93 : 0.10
  }
};

const raw = $json.text || '{}';
let parsed = {};
try { const m = raw.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch(e) {}
const conf = parsed.confidence_score || 0;
const needsL3 = conf < 0.75 || ['ILEGIBLE'].includes(parsed.firma_beneficiario) || ['ILEGIBLE'].includes(parsed.huella);
return { json: { ...$json, ...parsed, ocr_layer: 2, layer2_confidence: conf, needs_layer3: needsL3 } };

const raw = $json.text || '{}';
let parsed = {};
try { const m = raw.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : {}; } catch(e) {}
return { json: { ...$json, ...parsed, ocr_layer: 3, layer3_confidence: parsed.confidence_score || 0, alto_riesgo: true } };

function sino(v) {
  if (!v) return 'NO';
  const s = String(v).trim().toUpperCase();
  if (['SI','SI','S','YES','1','TRUE','COMPLETA','PRESENTE'].includes(s)) return 'SI';
  if (['NO','N','0','FALSE','AUSENTE','FALTANTE'].includes(s)) return 'NO';
  return 'ILEGIBLE';
}
function fdate(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? String(v) : d.toISOString().split('T')[0];
}
return { json: {
  acta_numero:            $json.acta_numero || ($json.name || '').replace('.pdf',''),
  nombre_responsable:     ($json.nombre_responsable || '').toUpperCase().trim(),
  cedula_responsable:     String($json.cedula_responsable || '').trim(),
  departamento:           ($json.departamento || '').trim(),
  municipio:              ($json.municipio || '').trim(),
  fecha_acta:             fdate($json.fecha_acta),
  nombre_beneficiario:    ($json.nombre_beneficiario || '').toUpperCase().trim(),
  cedula_beneficiario:    String($json.cedula_beneficiario || '').trim(),
  firma_beneficiario:     sino($json.firma_beneficiario),
  huella:                 sino($json.huella),
  info_responsable:       sino($json.info_responsable_completa),
  copia_doc_beneficiario: sino($json.copia_doc_beneficiario),
  copia_doc_autorizado:   sino($json.copia_doc_autorizado),
  entrega_tercero:        sino($json.entrega_tercero),
  novedades:              $json.novedades || '',
  ocr_layer_usado:        $json.ocr_layer || 1,
  ocr_confidence:         $json.layer3_confidence || $json.layer2_confidence || $json.layer1_confidence || 0,
  alto_riesgo_ocr:        !!$json.alto_riesgo,
  drive_file_id:          $json.id || '',
  procesado_en:           new Date().toISOString()
}};

